<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Personal Expense Tracker</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; margin: 0; padding: 20px; background-color: #f4f4f9; color: #333; }

        /* Container */
        .container { max-width: 800px; margin: auto; background: #fff; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); padding: 25px; }

        h1, h3 { margin-top: 0; color: #2c3e50; }

        /* Sections */
        .section { border-bottom: 1px solid #eee; padding-bottom: 20px; margin-bottom: 20px; }
        .filters-section { display: flex; gap: 15px; align-items: flex-end; flex-wrap: wrap; }

        /* Form Inputs */
        label { display: block; font-size: 0.9em; color: #666; margin-bottom: 4px; font-weight: 600;}
        input, select { padding: 10px; border: 1px solid #ddd; border-radius: 6px; width: 100%; box-sizing: border-box; }

        /* Button */
        button#add-expense { background-color: #27ae60; color: white; font-weight: bold; padding: 12px; margin-top: 5px; cursor: pointer; width: 100%; border-radius: 6px; border: none;}
        button#add-expense:hover { background-color: #2ecc71; }

        /* Error Message */
        .error-msg { color: #e74c3c; font-size: 0.95em; margin-top: 8px; min-height: 1.2em;}

        /* Summary Section */
        .summary-grid { display: flex; justify-content: space-between; align-items: center; background-color: #f8f9fa; padding: 15px; border-radius: 8px; }

        /* List Items */
        ul.expense-list { list-style-type: none; padding: 0; margin: 0; max-height: 400px; overflow-y: auto; border: 1px solid #eee; border-radius: 6px;}

        li.expense { display: flex; justify-content: space-between; align-items: center; padding: 15px; background-color: white; border-bottom: 1px solid #f0f0f0; }
        li.expense:last-child { border-bottom: none; }
        .expense-details span { margin-right: 12px; font-size: 0.9em; color: #555;}
        .amount-text { font-weight: bold; color: #333 !important; }

        /* Delete Button */
        button.exp-del { background-color: transparent; border: none; color: #e74c3c; cursor: pointer; padding: 8px; font-size: 1.2em;}
        button.exp-del:hover { text-decoration: underline; }

    </style>
</head>
<body>

<div class="container">
    <h1>Expense Tracker</h1>

    <!-- Entry Form -->
    <div class="section entry-form-section">
        <label for="amount">Amount ($)</label>
        <input type="number" step="0.01" id="amount" placeholder="Enter amount...">

        <label for="category">Category</label>
        <select id="category">
            <option value="" disabled selected>Select category</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
        </select>

        <label for="date">Date</label>
        <input type="date" id="date">

        <label for="note">Note (Optional)</label>
        <input type="text" id="note" placeholder="Enter note...">

        <button type="button" id="add-expense">Add Expense</button>

        <div class="error-msg" id="form-error"></div>
    </div>

    <!-- Filters -->
    <div class="section filters-section">
        <h3 style="width: 100%; margin-bottom: 5px;">Filters</h3>

        <label for="filter-category">Category:</label>
        <select id="filter-category" style="flex-grow: 1;">
            <option value="all">All Categories</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
        </select>

        <label for="filter-from" style="flex-grow: 1;">From:</label>
        <input type="date" id="filter-from">

        <label for="filter-to" style="flex-grow: 1;">To:</label>
        <input type="date" id="filter-to">
    </div>

    <!-- Summary -->
    <div class="section summary-section">
        <h3>Total</h3>
        <span id="total">$0.00</span>

        <ul style="display: flex; gap: 20px; list-style-type: none; padding-top:15px;">
            <!-- Per-category summaries defined here with data-cat attribute -->
            <li><strong>Groceries:</strong> <span class="cat-total" data-cat="groceries"></span></li>
            <li><strong>Transport:</strong> <span class="cat-total" data-cat="transport"></span></li>
            <li><strong>Bills:</strong> <span class="cat-total" data-cat="bills"></span></li>
            <li><strong>Fun:</strong> <span class="cat-total" data-cat="fun"></span></li>
        </ul>
    </div>

    <!-- Expense List -->
    <div id="list-section">
        <h3 style="margin-top:0;">Expenses</h3>
        <ul class="expense-list" id="expense-list">
            <!-- Expenses will be injected here -->
        </ul>
    </div>
</div>

<script>
document.addEventListener('DOMContentLoaded', () => {

    // DOM References
    const els = {
        amount: document.getElementById('amount'),
        category: document.getElementById('category'),
        date: document.getElementById('date'),
        note: document.getElementById('note'),
        addBtn: document.getElementById('add-expense'),
        formError: document.getElementById('form-error'),

        filterCategory: document.getElementById('filter-category'),
        filterFrom: document.getElementById('filter-from'),
        filterTo: document.getElementById('filter-to'),

        totalEl: document.getElementById('total'),
        catTotals: Array.from(document.querySelectorAll('.cat-total')), // Get all elements with class .cat-total

        expenseListUl: document.getElementById('expense-list')
    };

    // State & Persistence
    let expenses = [];

    function loadExpenses() {
        try {
            const raw = localStorage.getItem('expenses_tracker_v1');
            if (raw) {
                expenses = JSON.parse(raw);
            } else {
                expenses = [];
            }
        } catch (e) {
            console.error("Storage Error:", e);
            expenses = [];
        }
    }

    function saveExpenses() {
        localStorage.setItem('expenses_tracker_v1', JSON.stringify(expenses));
    }

    // Validation & Add Logic
    function addExpense() {
        const amountVal = els.amount.value.trim();
        const catVal = els.category.value;
        const dateVal = els.date.value.trim();

        let errorText = "";

        if (!amountVal) {
            errorText = "Amount is required.";
        } else {
            const num = parseFloat(amountVal);
            if (isNaN(num)) {
                errorText = "Amount must be a valid number.";
            } else if (num <= 0) {
                errorText = "Amount must be greater than zero.";
            }
        }

        if (!errorText && !dateVal) {
            errorText = "Date is required.";
        }

        if (errorText) {
            els.formError.textContent = errorText;
            // Don't add expense or save
            return false; 
        }

        // Valid Submission

        const amountNum = parseFloat(amountVal);

        expenses.push({
            id: Date.now().toString(),
            amount: amountNum,
            category: catVal,
            date: dateVal,
            note: els.note.value.trim()
        });

        saveExpenses();

        // Reset Amount field per contract. Clear Error too.
        els.formError.textContent = "";
        els.amount.value = ""; 

        render();
        return true;
    }

    function deleteExpense(id) {
        expenses = expenses.filter(e => e.id !== id);
        saveExpenses();
        render();
    }

    // Rendering & Filtering Logic
    function render() {
        const filterCatVal = els.filterCategory.value;
        const dateFrom = els.filterFrom.value.trim();
        const dateTo = els.filterTo.value.trim();

        // Filter Data
        let visibleExpenses = expenses.map(e => ({...e})); // Clone to avoid mutation issues during sort if any

        // Sort Newest First (Date Descending)
        visibleExpenses.sort((a, b) => {
            // Primary: Date string comparison works for YYYY-MM-DD
            return b.date.localeCompare(a.date); 
        });

        visibleExpenses = visibleExpenses.filter(e => {
            // Category Filter
            const isCatMatch = (filterCatVal === 'all') || (e.category === filterCatVal);

            // Date Range Filters
            let dateInRage = true;
            if (dateFrom) {
                // e.date >= fromDateString? Yes for ISO YYYY-MM-DD strings.
                dateInRage = dateInRage && (e.date >= dateFrom);
            }
            if (dateTo) {
                dateInRage = dateInRage && (e.date <= dateTo);
            }

            return isCatMatch && dateInRage;
        });

        // Update DOM List
        els.expenseListUl.innerHTML = '';

        visibleExpenses.forEach(exp => {
            const li = document.createElement('li');
            li.className = 'expense';

            const amtStr = exp.amount.toFixed(2);

            li.innerHTML = `
                <div class="expense-details">
                    <span class="amount-text">$${amtStr}</span>
                    <span>[${exp.category}]</span>
                    <span>${formatDateDisplay(exp.date)}</span>
                    ${exp.note ? `<br><em style="font-size:0.85em; color:#777;">"${exp.note}"</em>` : ''}
                </div>
                <button class="exp-del" title="Delete">✕</button>
            `;

            li.querySelector('.exp-del').addEventListener('click', () => {
                deleteExpense(exp.id);
            });

            els.expenseListUl.appendChild(li);
        });

        // Calculate Totals (based on visibleExpenses)
        let grandTotal = 0;

        const catTotalsAccumulator = {};
        ['groceries', 'transport', 'bills', 'fun'].forEach(cat => {
            catTotalsAccumulator[cat] = 0;
        });

        visibleExpenses.forEach(exp => {
            grandTotal += exp.amount;
            if (Object.prototype.hasOwnProperty.call(catTotalsAccumulator, exp.category)) {
                catTotalsAccumulator[exp.category] += exp.amount;
            } else {
                // Fallback for unexpected category values not in known list
                console.warn("Unknown category:", exp.category);
            }
        });

        els.totalEl.textContent = `$${grandTotal.toFixed(2)}`;

        els.catTotals.forEach(el => {
            const catKey = el.dataset.cat;
            if (catKey && catTotalsAccumulator.hasOwnProperty(catKey)) {
                // If total is 0, do we show text? Prompt says "contains that category's visible total". 
                // Showing "0.00" or empty string might differ based on implementation preference. 
                // Usually showing 0.00 makes it clear there are no expenses for this category in the current view.
                el.textContent = `$${catTotalsAccumulator[catKey].toFixed(2)}`;
            } else {
                 el.textContent = '';
            }
        });
    }

    // Helper Date Formatting (optional, simple YYYY-MM-DD -> readable if desired? 
    // Prompt shows `Date: ...` in row. I'll keep it ISO or formatted simply.)
    function formatDateDisplay(dateStr) {
        return dateStr; // Keeps consistency with input format logic

        // Or convert to human friendly:
        /*
        const [y, m, d] = dateStr.split('-');
        return `${m}/${d}/${y}`; 
        */
    }

    // Initialize & Event Listeners

    els.addBtn.addEventListener('click', addExpense);

    // Filter Events (change events trigger re-render)
    els.filterCategory.addEventListener('change', render);
    els.filterFrom.addEventListener('input', render); // input allows live typing of date? usually change is better for date, but prompt implies inputs. 
                                                        // "date inputs... rows outside the range hide". I'll use 'input' or 'change'.
                                                        // Standard practice: 'input' gives immediate feedback as user types, though incomplete dates might not filter yet (empty string).
                                                        // Let's stick to 'change' for date to ensure valid full value. 
                                                        // But if user selects from dropdown? 'change' triggers on select.
    els.filterFrom.addEventListener('change', render);
    els.filterTo.addEventListener('input', render);
    els.filterTo.addEventListener('change', render);

    function init() {
        loadExpenses();

        // Set default Date for convenience (optional, but helpful)
        const today = new Date().toISOString().split('T')[0];
        if (!els.date.value) {
            els.date.value = today;
        }

        render();
    }

    init();
});
</script>

</body>
</html>
